161	SEC-DOC-AUTH-001	1	mssql	SELECT\n    name,\n    'SQL logins that are enabled (potential default targets)' Risk_pattern \nFROM sys.sql_logins\nWHERE is_disabled = 0\nunion all \nSELECT\n    name,\n    'logins NOT enforcing password policy (high risk)'    \nFROM sys.sql_logins\nWHERE is_policy_checked = 0\n   OR is_expiration_checked = 0\nunion all \nSELECT\n    name,\n    'logins with passwords never changed'\nFROM sys.sql_logins\nWHERE create_date = modify_date\n  AND is_disabled = 0\nunion all \nSELECT name , \n'common vendor / default account names'\nFROM sys.sql_logins\nWHERE name IN (\n    'admin',\n    'administrator',\n    'sa',\n    'root',\n    'test',\n    'guest'\n)\nunion all \nSELECT\n    name , \n    'sa login is enabled (major red flag)'\nFROM sys.sql_logins\nWHERE name = 'sa'\nunion all \nSELECT\n    name,\n    'SQL-auth logins (higher risk than Windows auth)'\nFROM sys.sql_logins\nWHERE type_desc = 'SQL_LOGIN';	2026-01-05 11:24:18.78563	t	\N	\N
162	SEC-DOC-AUTH-001	2	mssql	SELECT name, 'Detect SQL Server Default Logins (e.g., sa, admin)' Risk_Pattern\nFROM sys.sql_logins\nWHERE name IN ('sa', 'admin', 'root', 'guest', 'test')\nunion all \nSELECT name, 'Logins with Weak or Default Password Policies'\nFROM sys.sql_logins\nWHERE is_policy_checked = 0 OR is_expiration_checked = 0\nunion all \nSELECT name, 'sa Login is Enabled'\nFROM sys.sql_logins\nWHERE name = 'sa'\nunion all \nSELECT SERVERPROPERTY('IsIntegratedSecurityOnly') AS IsWindowsAuthenticationOnly  ,  'SQL Server Authentication Mode'\nunion all \nSELECT name, 'Unchanged sa Password'\nFROM sys.sql_logins\nWHERE name = 'sa'\nunion all \nSELECT name, 'Default Database (master) is In Use for Non-System Users'\nFROM sys.sql_logins\nWHERE default_database_name = 'master'\nunion all\nSELECT \n    dp.name AS principal_name  , 'Missing or Default Permissions on Critical Databases'\nFROM sys.database_permissions p\nJOIN sys.objects o ON p.major_id = o.object_id\nJOIN sys.database_principals dp ON p.grantee_principal_id = dp.principal_id\nWHERE o.name IN ('master', 'msdb')	2026-01-05 11:24:18.78563	t	\N	\N
163	SEC-DOC-AUTH-001	3	mssql	SELECT\n    name,'built-in sa login is enabled (high-risk)' risk_pattern\nFROM sys.sql_logins\nWHERE name NOT LIKE '##%'\nunion all \nSELECT\n    name , \n    'SQL logins enforce password policy'\nFROM sys.server_principals\nWHERE type_desc = 'SQL_LOGIN'\n  AND name IN ('sa', 'admin', 'test', 'user', 'sqladmin')\nunion all \nSELECT\n    name,\n'well-known default or vendor logins'\nFROM sys.server_principals\nWHERE type_desc = 'SQL_LOGIN'\n  AND name IN ('sa', 'admin', 'test', 'user', 'sqladmin')\nunion all \nSELECT\n    name,\n    'SQL logins created immediately after installation'\nFROM sys.sql_logins\nunion all \nSELECT\n    sp.name , \n    'SQL logins with sysadmin privileges'\nFROM sys.server_principals sp\nJOIN sys.server_role_members srm\n    ON sp.principal_id = srm.member_principal_id\nJOIN sys.server_principals sr\n    ON srm.role_principal_id = sr.principal_id\nWHERE sr.name = 'sysadmin'\n	2026-01-05 11:24:18.78563	t	\N	\N
